import re,os
root='AlgebraicJacobian'
def mod2path(m):
    return m.replace('.','/')+'.lean'
seen=set()
stack=['AlgebraicJacobian']
while stack:
    m=stack.pop()
    if m in seen: continue
    p=mod2path(m)
    if not os.path.exists(p): continue
    seen.add(m)
    for line in open(p):
        mm=re.match(r'import\s+(AlgebraicJacobian[\w.]*)',line)
        if mm: stack.append(mm.group(1))
all_mods=set()
for d,_,fs in os.walk(root):
    for f in fs:
        if f.endswith('.lean'):
            all_mods.add(os.path.join(d,f)[:-5].replace('/','.'))
all_mods.add('AlgebraicJacobian')
un=sorted(all_mods-seen)
print("total",len(all_mods),"in cone",len(seen),"unrooted",len(un))
for u in un: print(" ",u)
EOF
